import sys

try:
    from pypdf import PdfReader
except ImportError:
    try:
        from PyPDF2 import PdfReader
    except ImportError:
        print("NO_PDF_LIB")
        sys.exit(0)

reader = PdfReader(sys.argv[1])
print("PAGES:", len(reader.pages))
for i, page in enumerate(reader.pages, 1):
    print("--- page %d ---" % i)
    print(page.extract_text())
